pid = os.fork()
if pid == 0:
    arm_same_lifetime()
    os.setsid()
    signal.signal(signal.SIGTERM, signal.SIG_IGN)
    Path("descendant.pid").write_text(str(os.getpid()))
    while within_lifetime(): bounded_sleep(1)
else:
    while within_lifetime(): bounded_sleep(1)

pid = os.fork()
if pid == 0:
    arm_same_lifetime()
    Path("descendant.pid").write_text(str(os.getpid()))
    while within_lifetime(): bounded_sleep(1)
else:
    while not Path("descendant.pid").exists(): bounded_sleep(0.005)
    os._exit(0)
